sections.body:
保存为 quantization-audit.mjs，运行 node quantization-audit.mjs，无额外依赖。每组的两个数分别对应 A、B；outside 统计原值落在 [0,R] 外的数量，等于边界不算超范围。它不同于“整数结果恰好等于 255”的计数。

```js
/**
 * @file Inspect unsigned 8-bit quantization with synthetic NPC scores.
 * @author liliwei
 * @date 2026-11-14
 * @LastEditors liliwei
 * @LastEditTime 2026-11-14
 */

/** @param {number} x Finite number. @returns {number} Nearest integer, ties to even. */
export function roundEven(x) {
  const low = Math.floor(x), fraction = x - low;
  if (fraction < 0.5) return low;
  if (fraction > 0.5) return low + 1;
  return low % 2 === 0 ? low : low + 1;
}

/** @param {number} x Scalar. @param {number} max Range ceiling. @returns {object} Q/DQ record. */
export function qdq(x, max) {
  if (!Number.isFinite(x) || Math.abs(x) > 1e6 ||
      !Number.isFinite(max) || max < 1e-6 || max > 1e6) {
    throw new RangeError('Invalid scalar or quantization range');
  }
  const scale = max / 255;
  const q = Math.max(0, Math.min(255, roundEven(x / scale)));
  return { q, restored: q * scale, outside: x < 0 || x > max };
}

/** @param {number[]} pair Two scores. @returns {string} Winner; A wins ties. */
export function winner(pair) { return pair[1] > pair[0] ? 'B' : 'A'; }

// These are hand-written examples, not neural network measurements.
export const samples = [
  { id: 'ordinary', scores: [0.2, 0.8] },
  { id: 'close', scores: [0.501, 0.509] },
  { id: 'boss', scores: [1.6, 2.2] },
];

/** @param {number} max Range ceiling. @returns {object} Scalar and decision differences. */
export function audit(max) {
  let outside = 0, changed = 0, absoluteError = 0;
  const rows = samples.map(({ id, scores }) => {
    const records = scores.map(x => qdq(x, max));
    const restored = records.map(r => r.restored);
    outside += records.filter(r => r.outside).length;
    absoluteError += restored.reduce((sum, x, i) => sum + Math.abs(x - scores[i]), 0);
    const before = winner(scores), after = winner(restored);
    if (before !== after) changed++;
    return { id, q: records.map(r => r.q), restored, before, after };
  });
  return { max, step: max / 255, outside, scalarCount: 6,
    changed, decisionCount: 3, mae: absoluteError / 6, rows };
}

for (const max of [1, 4, 2.5]) console.log(JSON.stringify(audit(max)));
```

输入数量级限制仅用于教学防误用。计算使用 JavaScript Number，不是 ONNX 的 FP32 内核；没有训练模型、存储真正的 uint8 权重或执行整数矩阵乘法，因此不能对这段脚本计时后宣布模型加速。
